subscriptions.schema:
message gram.sigint.v1.Reading {
	optional int32 __oneof_result (INT(32,true));
	required group __pubsub {
		required binary message_id (STRING);
		required int64 received_micros (INT(64,true));
		required binary topic (STRING);
	}
	optional group account {
		required boolean __present;
		optional binary account_type (STRING);
		optional binary billing_mode (STRING);
		optional binary user_account_id (STRING);
	}
	optional group actor {
		required boolean __present;
		optional binary external_user_id (STRING);
		optional binary user_email (STRING);
		optional binary user_id (STRING);
	}
	optional binary assistant_id (STRING);
	optional binary billing_user_id (STRING);
	optional group choice {
		required boolean __present;
		optional double confidence;
		required group distribution (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
		optional binary selected_signal_id (STRING);
		optional binary selected_signal_slug (STRING);
	}
	optional binary compiler_version (STRING);
	optional binary configured_model (STRING);
	optional binary definition_hash (STRING);
	optional binary evaluated_at (STRING);
	optional binary evaluation_attempt_id (STRING);
	optional group event {
		optional int32 __oneof_context (INT(32,true));
		required boolean __present;
		optional group conversation_message {
			required boolean __present;
			optional binary conversation_id (STRING);
			optional int32 role (INT(32,true));
		}
		optional binary id (STRING);
		optional binary kind (STRING);
		optional binary occurred_at (STRING);
		optional group tool_call {
			required boolean __present;
			optional binary mcp_server_id (STRING);
			optional binary tool_call_id (STRING);
			optional binary tool_name (STRING);
		}
	}
	optional binary id (STRING);
	required group models (LIST) {
		repeated group list {
			required binary element (STRING);
		}
	}
	optional group multi_label {
		required boolean __present;
		required group signals (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
	}
	optional binary organization_id (STRING);
	optional binary project_id (STRING);
	optional boolean replayed;
	optional group score {
		required boolean __present;
		optional double confidence;
		required group distribution (LIST) {
			repeated group list {
				required group element {
					required boolean __present;
					optional double probability;
					optional binary signal_id (STRING);
					optional binary signal_slug (STRING);
				}
			}
		}
		optional double expected_index;
	}
	optional binary sensor_id (STRING);
	optional binary sensor_slug (STRING);
	optional binary source (STRING);
}
